//! Readable copy of the device's media partition over AFC:
//! camera roll originals (DCIM), edited versions (PhotoData/Mutations), or everything.

use std::path::Path;

use anyhow::{bail, Result};
use idevice::afc::AfcClient;
use idevice::usbmuxd::UsbmuxdDevice;

use crate::afc_copy::{self, RemoteFile};
use crate::device;
use crate::util::{bytes_bar, human_bytes, spinner, Stats};

const MAX_ATTEMPTS: u32 = 4;

/// Thumbnails and caches are regenerated by iOS; never worth copying.
const ALWAYS_EXCLUDE: [&str; 3] = ["PhotoData/Thumbnails", "PhotoData/Caches", "PhotoData/FileCache"];

async fn exists(afc: &mut AfcClient, path: &str) -> Result<bool, idevice::IdeviceError> {
    match afc.get_file_info(path.to_string()).await {
        Ok(_) => Ok(true),
        // The phone refusing to answer is not "the folder is missing".
        Err(e) if afc_copy::is_fatal(&e) => Err(e),
        Err(_) => Ok(false),
    }
}

pub async fn run(
    dev: &UsbmuxdDevice,
    out: &Path,
    everything: bool,
    extra_exclude: &[String],
    verify: bool,
    prune: Option<&crate::prune::Options>,
) -> Result<Stats> {
    // --delete-all exists precisely because the iPhone may not be able to hash its own files:
    // don't spend an hour on a pass that cannot succeed, and that is what exhausts the phone.
    let deleting_all = prune.is_some_and(|p| p.all);
    let verify = !deleting_all && (verify || prune.is_some());
    let p = device::provider(dev)?;
    afc_copy::ensure_dir(out)?;

    let roots: Vec<&str> = if everything { vec!["/"] } else { vec!["DCIM", "PhotoData/Mutations"] };
    let mut exclude: Vec<String> = ALWAYS_EXCLUDE.iter().map(|s| s.to_string()).collect();
    exclude.extend(extra_exclude.iter().cloned());

    // 1) Scan (reconnecting if the phone drops the connection, e.g. it locked).
    let mut stats = Stats::default();
    let mut attempt = 0;
    let files: Vec<RemoteFile> = loop {
        attempt += 1;
        let mut afc: AfcClient = device::connect(&p, "file access (AFC)").await?;
        let sp = spinner("Scanning device media…");
        let mut found = Vec::new();
        let mut scan_stats = Stats::default();
        let mut failure: Option<idevice::IdeviceError> = None;
        for r in &roots {
            if *r != "/" {
                match exists(&mut afc, r).await {
                    Ok(true) => {}
                    Ok(false) => continue,
                    Err(e) => {
                        failure = Some(e);
                        break;
                    }
                }
            }
            match afc_copy::scan(&mut afc, r, &exclude, &mut scan_stats).await {
                Ok(f) => found.extend(f),
                Err(e) => {
                    failure = Some(e);
                    break;
                }
            }
        }
        sp.finish_and_clear();
        match failure {
            None => {
                stats.merge(scan_stats);
                break found;
            }
            Some(e) if attempt < MAX_ATTEMPTS => {
                crate::util::say(&format!("device stopped answering while scanning ({}); retrying…", afc_copy::explain(&e)));
                afc_copy::retry_pause().await;
            }
            Some(e) => bail!("scanning failed repeatedly: {}", afc_copy::explain(&e)),
        }
    };

    let total = afc_copy::pending_bytes(&files);
    crate::util::say(&format!("photos & videos: {} files, {} on device", files.len(), human_bytes(total)));
    if let Some(free) = crate::util::free_space(out) {
        if free < total {
            stats.notes.push(format!(
                "destination may be too small: {} free, up to {} needed",
                human_bytes(free),
                human_bytes(total)
            ));
            crate::util::say(&format!("warning: only {} free at destination", human_bytes(free)));
        }
    }

    // 2) Copy. On a dropped connection, reconnect and resume (copied files are skipped).
    let bar = bytes_bar(total, "media");
    let mut attempt = 0;
    let mut copied_in_earlier_passes = 0u64;
    loop {
        attempt += 1;
        bar.set_position(0);
        let mut run_stats = Stats::default();
        let mut afc: AfcClient = device::connect(&p, "file access (AFC)").await?;
        match afc_copy::copy_all(&mut afc, &files, "", out, &bar, &mut run_stats).await {
            Ok(()) => {
                // Files copied by an interrupted pass show up as "unchanged" in this one.
                run_stats.files_skipped_unchanged =
                    run_stats.files_skipped_unchanged.saturating_sub(copied_in_earlier_passes);
                stats.merge(run_stats);
                break;
            }
            Err(e) if attempt < MAX_ATTEMPTS => {
                copied_in_earlier_passes += run_stats.files_copied;
                stats.files_copied += run_stats.files_copied;
                stats.bytes_copied += run_stats.bytes_copied;
                stats.errors.extend(run_stats.errors);
                bar.println(format!("  device stopped answering ({}); keep the iPhone unlocked. Resuming…", afc_copy::explain(&e)));
                crate::util::say("device stopped answering; keep the iPhone unlocked. Resuming…");
                afc_copy::retry_pause().await;
            }
            Err(e) => {
                bar.finish_and_clear();
                bail!("copy failed repeatedly: {}", afc_copy::explain(&e));
            }
        }
    }
    bar.finish_and_clear();

    if verify {
        let r = crate::verify::run(&p, &files, out, &mut stats).await?;
        let dcim_total = files.iter().filter(|f| f.path.starts_with("DCIM/")).count();
        let dcim_ok = r.verified.iter().filter(|f| f.starts_with("DCIM/")).count();
        stats.notes.push(format!(
            "verified {} of {} files against the iPhone's own hashes ({} failed); details in {}",
            r.verified.len(),
            files.len(),
            r.failed.len(),
            out.join(crate::verify::MANIFEST).display()
        ));
        if r.reused > 0 {
            stats.notes.push(format!(
                "{} of those were already verified and unchanged on both sides, so they were not hashed again",
                r.reused
            ));
        }
        match crate::verify::safe_before(&files, &r.failed) {
            None if dcim_total > 0 => stats.notes.push(format!(
                "all {dcim_ok} camera-roll files (DCIM) are verified on this computer"
            )),
            None => {}
            Some(t) => stats.notes.push(format!(
                "camera-roll files dated before {} are verified; newer ones have failures, see errors",
                crate::verify::fmt_time(t)
            )),
        }
    }

    if let Some(opts) = prune {
        crate::prune::run(&p, &files, out, opts, &mut stats).await?;
    }

    if !everything && (!stats.errors.is_empty() || files.is_empty()) {
        stats.notes.push(
            "If Settings > Photos > 'Optimize iPhone Storage' is on, iCloud originals are not on the \
             phone; switch to 'Download and Keep Originals', wait for the download, and run again."
                .into(),
        );
    }
    Ok(stats)
}
